            position: relative;
            z-index: 2;
            pointer-events: none;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            height: 100vh;
            padding: 40px;
            box-sizing: border-box;
        }

        .header {
            pointer-events: auto;
        }

        h1 {
            font-size: 3rem;
            margin: 0;
            letter-spacing: -2px;
            text-transform: uppercase;
            background: linear-gradient(to right, #ffffff, #5c6bc0);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }

        .tagline {
            font-size: 1rem;
            letter-spacing: 4px;
            color: #5c6bc0;
            margin-top: 5px;
        }

        .footer {
