            align-items: flex-end;
            font-size: 0.8rem;
            color: rgba(255, 255, 255, 0.5);
        }

        .stats {
            pointer-events: auto;
            text-align: right;
        }

        .stat-item {
            margin-bottom: 10px;
        }

        .stat-value {
            display: block;
            font-size: 1.2rem;
            color: #fff;
